{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Ensure every security group and rule has a description",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The security group 'vault' has ingress rules without descriptions, which can make it difficult to understand the purpose of these rules."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Ingress rule exposes Vault to the entire internet",
      "resource": "aws_security_group.vault",
      "severity": "CRITICAL",
      "explanation": "The security group 'vault' allows ingress from '0.0.0.0/0', potentially exposing Vault to the entire internet."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"vault\" {\n  name        = \"vault\"\n  description = \"Ingress for Vault\"\n  vpc_id      = aws_vpc.my_vpc.id\n  dynamic \"ingress\" {\n    iterator = port\n    for_each = var.ingress_ports\n    content {\n      from_port   = port.value\n      to_port     = port.value\n      protocol    = \"tcp\"\n      cidr_blocks = [\"0.0.0.0/0\"]\n      description = \"Allow incoming traffic on port ${port.value}\"\n    }\n  }\n}",
  "fix_summary": "Added descriptions to the ingress rules and kept the original cidr_blocks as is, though it's highly recommended to restrict the cidr_blocks to a more limited range for security reasons."
}
